import secrets
from decimal import Decimal
from django.core.management.base import BaseCommand, CommandError
from django.contrib.auth.models import User, Group, Permission
from django.db import transaction
from erp.models import Site, SiteAccess, Product, Partner, Order, OrderLine, Production, QualityTest
from erp.services import move_stock, audit, transition_order

class Command(BaseCommand):
    help = 'Create fictional demo records and operator, approver and administrator accounts. Run on an empty local database.'
    def add_arguments(self, parser):
        parser.add_argument('--password', help='Optional local demo password; a random password is generated by default.')
    @transaction.atomic
    def handle(self, *args, **options):
        if User.objects.filter(username__in=['admin', 'operator', 'approver']).exists():
            raise CommandError('Demo accounts already exist. No records changed. Use your existing credentials.')
        password = options['password'] or secrets.token_urlsafe(12)
        admin = User.objects.create_superuser('admin', 'admin@example.test', password)
        operator = User.objects.create_user('operator', password=password, first_name='Plant', last_name='Operator')
        approver = User.objects.create_user('approver', password=password, first_name='Operations', last_name='Approver')
        makers, _ = Group.objects.get_or_create(name='Operations maker')
        checkers, _ = Group.objects.get_or_create(name='Operations approver')
        views = Permission.objects.filter(content_type__app_label='erp', codename__startswith='view_')
        makers.permissions.set(views)
        makers.permissions.add(*Permission.objects.filter(content_type__app_label='erp', codename__in=['add_order', 'change_order', 'add_production', 'complete_production', 'add_qualitytest', 'post_order']))
        checkers.permissions.set(views)
        checkers.permissions.add(*Permission.objects.filter(content_type__app_label='erp', codename__in=['approve_order', 'release_production', 'post_order']))
        operator.groups.add(makers)
        approver.groups.add(checkers)
        plant = Site.objects.create(code='PLT-01', name='Satna Cement Works', kind='Plant', address='Satna, Madhya Pradesh (fictional demo site)')
        depot = Site.objects.create(code='DPT-01', name='Bhopal Distribution Depot', kind='Depot', address='Bhopal, Madhya Pradesh (fictional demo site)')
        for user in [operator, approver]:
            for site in [plant, depot]: SiteAccess.objects.create(user=user, site=site)
        opc = Product.objects.create(code='CEM-OPC53', name='OPC 53 Grade · 50 kg', category='Cement', unit='BAG', bag_weight_kg=50, hsn='2523', reorder_level=500)
        ppc = Product.objects.create(code='CEM-PPC', name='Portland Pozzolana · 50 kg', category='Cement', unit='BAG', bag_weight_kg=50, hsn='2523', reorder_level=400)
        bulk = Product.objects.create(code='CEM-BULK', name='OPC Bulk Cement', category='Cement', unit='MT', hsn='2523', reorder_level=100)
        clinker = Product.objects.create(code='RM-CLK', name='Cement clinker', category='Raw material', unit='MT', reorder_level=200)
        gypsum = Product.objects.create(code='RM-GYP', name='Natural gypsum', category='Raw material', unit='MT', reorder_level=50)
        dealer = Partner.objects.create(code='DLR-001', name='Sharma Building Materials', kind='Dealer', territory='Bhopal', credit_limit=5000000, phone='9000000001', address='Demo dealer address, Bhopal')
        dealer2 = Partner.objects.create(code='DLR-002', name='Central India Traders', kind='Dealer', territory='Indore', credit_limit=3000000, phone='9000000002')
        supplier = Partner.objects.create(code='SUP-001', name='Vindhya Mineral Supply', kind='Supplier', territory='Satna')
        Partner.objects.create(code='TRN-001', name='Narmada Logistics', kind='Transporter', territory='Madhya Pradesh')
        for index, (site, product, quantity) in enumerate([(plant, opc, 12500), (plant, ppc, 8400), (plant, bulk, 360), (plant, clinker, 920), (plant, gypsum, 35), (depot, opc, 2400), (depot, ppc, 380)]):
            movement = move_stock(admin, site, product, Decimal(quantity), f'demo:opening:{index}', 'Opening', 'Fictional demo opening balance')
            audit(admin, 'Opening stock posted', movement)
        for kind, partner, product, quantity, rate, status in [('Sale', dealer, opc, 600, 340, 'Approved'), ('Sale', dealer2, ppc, 450, 320, 'Submitted'), ('Purchase', supplier, clinker, 150, 2800, 'Submitted'), ('Sale', dealer, ppc, 200, 325, 'Draft'), ('Sale', dealer2, opc, 300, 345, 'Completed')]:
            order = Order.objects.create(site=plant, kind=kind, partner=partner, created_by=operator)
            OrderLine.objects.create(order=order, product=product, quantity=quantity, rate=rate)
            audit(operator, 'Order created', order)
            if status != 'Draft': transition_order(operator, order.pk, 'submit')
            if status in ['Approved', 'Completed']: transition_order(approver, order.pk, 'approve')
            if status == 'Completed': transition_order(approver, order.pk, 'post')
        held = Production.objects.create(site=plant, product=opc, batch='DEMO-OPC-001', shift='A', planned_quantity=5000, actual_quantity=4950, status='Quality hold', created_by=operator)
        audit(operator, 'Production quality hold', held)
        QualityTest.objects.create(site=plant, production=held, test_name='Fineness', result='Within demo specification', disposition='Pass', created_by=approver, notes='Illustrative only; not a real laboratory certificate')
        planned = Production.objects.create(site=plant, product=ppc, batch='DEMO-PPC-002', shift='B', planned_quantity=4000, actual_quantity=3950, created_by=operator)
        audit(operator, 'Production created', planned)
        self.stdout.write(self.style.SUCCESS('Demo ready. All sample records are fictional.'))
        self.stdout.write(f'Users: admin / operator / approver\nPassword for these local demo accounts: {password}\nSave this password; it is not stored in a plaintext file.')
